import os, sys

BASE = "/srv/dokumen"

def unduh(nama):
    p = os.path.normpath(os.path.join(BASE, nama))
    if not p.startswith(BASE + "/"):
        return "DITOLAK"
    return p

for nama in sys.stdin.read().split():
    print(unduh(nama))

