import re, sys

def perintah_ping(host):
    if not re.fullmatch(r"[A-Za-z0-9.-]+", host):
        return "DITOLAK"
    return ["ping", "-c", "1", host]

for host in sys.stdin.read().split():
    print(perintah_ping(host))

